-- Check what values onlineuse and mobileuse can have
SELECT DISTINCT chaninvdatablock->>'onlineuse' as online_use FROM bank_and_transactions;
SELECT DISTINCT chaninvdatablock->>'mobileuse' as mobile_use FROM bank_and_transactions;
SELECT DISTINCT chaninvdatablock->>'autopay' as autopay FROM bank_and_transactions;

-- Check all values for onlineuse, mobileuse, autopay
SELECT chaninvdatablock->>'onlineuse' as online_use, chaninvdatablock->>'mobileuse' as mobile_use, chaninvdatablock->>'autopay' as autopay, COUNT(*) 
FROM bank_and_transactions GROUP BY 1,2,3 ORDER BY 1,2,3;

-- Maybe cohort is based on scoredate quarter + some tenure calculation
